A medal table with uneven rows crashes inside this maximum hunt:
int[][] g = {{2, 7, 1}, {5, 3}, {9, 4, 6, 8}};
int m = g[0][0];
for (int r = 0; r < g.length; r++) { for (int c = 0; c < g[0].length; c++) { if (g[r][c] > m) { m = g[r][c]; } } }
